<?php
try {  $pdo = new PDO('mysql:host=localhost;dbname=petron_pos_db_secure', 'root', '');  // Check inventory_products table  echo "=== INVENTORY_PRODUCTS TABLE ===\n";  $stmt = $pdo->query("SELECT COUNT(*) as total FROM inventory_products");  $count = $stmt->fetchColumn();  echo "Total products: $count\n\n";  if ($count > 0) {  echo "Sample products:\n";  $stmt = $pdo->query("SELECT id, product_name, category, status FROM inventory_products LIMIT 10");  while($row = $stmt->fetch(PDO::FETCH_ASSOC)) {  echo "- ID: {$row['id']}, Name: {$row['product_name']}, Category: {$row['category']}, Status: {$row['status']}\n";  }  }  echo "\n=== STATION_INVENTORY TABLE ===\n";  $stmt = $pdo->query("SELECT COUNT(*) as total FROM station_inventory");  $count = $stmt->fetchColumn();  echo "Total station inventory records: $count\n\n";  if ($count > 0) {  echo "Sample station inventory:\n";  $stmt = $pdo->query("SELECT station_id, product_id, stock_level FROM station_inventory LIMIT 10");  while($row = $stmt->fetch(PDO::FETCH_ASSOC)) {  echo "- Station: {$row['station_id']}, Product: {$row['product_id']}, Stock: {$row['stock_level']}\n";  }  }  echo "\n=== CHECKING FOR MERCHANDISE (NON-FUEL) PRODUCTS ===\n";  $stmt = $pdo->query("SELECT COUNT(*) as total FROM inventory_products WHERE LOWER(COALESCE(category, '')) <> 'fuel'");  $count = $stmt->fetchColumn();  echo "Non-fuel products: $count\n";  } catch(Exception $e) {  echo "Error: " . $e->getMessage();
}
